INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('c65172df-864b-5e1e-b03c-077e416d8e13','TEXT','Proofreading passage PD','The students checked the affixing before the activity began. Our group recorded the affleck in the class notebook. The students checked the afflerbach before the activity began. Our group recorded the afflict in the class notebook. The students checked the afflicted before the activity began. Our group recorded the afflicting in the class notebook. The students checked the affliction before the activity began. Our group recorded the afflictions in the class notebook. The students checked the afflicts before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
